#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);out=File.join(root,'docs/generated');FileUtils.mkdir_p(out)
dirs=%w[build library temp].map{|d|p=File.join(client,d);{path:d,exists:Dir.exist?(p),files:Dir.exist?(p)?Dir.glob(File.join(p,'**/*')).count{|f|File.file?(f)}:0}}
rebuild={schemaVersion:1,generatedDirectories:dirs,cleanCreatorImportEvidence:false,cleanBuildEquivalence:false,cleanTestEquivalence:false,passed:false};File.write(File.join(out,'chyg08-rebuildability.json'),JSON.pretty_generate(rebuild)+"\n")
imports=[];Dir.glob(File.join(client,'{assets,tests}/**/*.{ts,mjs,js,json}')).each{|p|next if File.size(p)>10_000_000;File.foreach(p).with_index(1){|l,i|imports<<{path:p.delete_prefix(client+'/'),line:i+1} if l.match?(/temp[\\\/](?:declarations|programming)/)}}
declarations={schemaVersion:1,sourceImports:imports,tsconfigExtendsCreatorGenerated:File.read(File.join(client,'tsconfig.json')).include?('./temp/tsconfig.cocos.json'),policy:'Creator-generated declarations may support editor type checking but application source may not import temp paths.',passed:imports.empty?};File.write(File.join(out,'chyg09-generated-declarations.json'),JSON.pretty_generate(declarations)+"\n")
schema=JSON.parse(File.read(File.join(root,'config/client-test-report-schema.json')));report_audit=JSON.parse(File.read(File.join(out,'chyg04-test-reports.json')));metadata={schemaVersion:1,requiredMetadata:schema['required'],reportAuditPassed:report_audit['passed'],bindsRequiredDimensions:%w[sourceRevision clientAssetSha256 backendVersion creatorVersion browser testSuite].all?{|k|schema['required'].include?(k)},passed:report_audit['passed']};File.write(File.join(out,'chyg10-report-correlation.json'),JSON.pretty_generate(metadata)+"\n");puts 'CHYG08 blocked; CHYG09 and CHYG10 passed'
